import {groundAt,resolveRadio,PRESETS} from './physics.mjs';
export const MODES={video:{name:'Live video',rate:10000,transfer:2,detail:'10 Mbps · View rock textures · 2 minutes · Stronger signal required'},summary:{name:'Science summary',rate:1000,transfer:20,detail:'1 Mbps · Measurements and compressed photos · 20 minutes · More signal margin'}};
export function slopeAt(t,p){const d=t.res*2;const z=[groundAt(t,p[0]-d,p[1]),groundAt(t,p[0]+d,p[1]),groundAt(t,p[0],p[1]-d),groundAt(t,p[0],p[1]+d)];return z.every(Number.isFinite)?Math.atan(Math.hypot((z[1]-z[0])/(2*d),(z[3]-z[2])/(2*d)))*180/Math.PI:NaN;}
export function siteCost(t,p){const slope=slopeAt(t,p);return {slope,minutes:Number.isFinite(slope)?(slope<10?8:slope<20?14:22):Infinity};}
export function missionBudget(t,relays,mode){const install=relays.reduce((n,p)=>n+siteCost(t,p).minutes,0),transfer=MODES[mode].transfer;return {install,transfer,total:install+transfer,ok:install+transfer<=45};}
export function scienceRadio(mode){return resolveRadio({...PRESETS.sband,rate_kbps:MODES[mode].rate});}
export function sciencePanel(onChange){let mode='video';const panel=document.createElement('section');panel.className='notice';panel.innerHTML=`<small>SCIENCE MISSION · RECOVER RECORDS FROM TWO ROCK SITES</small><h2>What will you send, and where will you place the relay?</h2><p>Crew 1 studies rock layers; crew 2 examines comparison samples. Connect both crews and transmit their records within 45 minutes.</p><p><strong>First, choose a transmission mode.</strong> Live video is faster but needs a stronger signal. A science summary works with a weaker signal but takes longer. You can change your choice later.</p><fieldset><legend>1. Choose transmission mode</legend>${Object.entries(MODES).map(([id,m])=>`<label style="display:block;margin:12px 0"><input type="radio" name="science-mode" value="${id}" ${id==='video'?'checked':''}> <strong>${m.name}</strong> — ${m.detail}</label>`).join('')}</fieldset><p>High ground can improve visibility, but steep slopes take longer to set up. Select a site to inspect its slope and profile.</p><p id="science-budget" role="status"></p><details><summary>Game assumptions and data</summary><p>Slope is estimated over roughly 32 m. Setup takes 8 minutes below 10°, 14 minutes at 10–20°, and 22 minutes at 20° or more. Time limits, setup times and objectives are fictional educational assumptions, not operational safety criteria. Travel time is excluded. Both modes assume the same data volume.</p></details>`;document.querySelector('.layout').before(panel);panel.addEventListener('change',e=>{if(e.target.name==='science-mode'){mode=e.target.value;onChange(mode);}});return {get mode(){return mode},update(t,relays){const b=missionBudget(t,relays,mode);panel.querySelector('#science-budget').textContent=`Planned time: setup ${b.install} min + transmission ${b.transfer} min = ${b.total} / 45 min (not a real-time timer) · ${b.ok?'Within time limit':'Over time — consider a gentler site or faster transmission'}`;},describe(t,p){const c=siteCost(t,p);return `<p><strong>Site survey:</strong> Estimated slope: approx. ${c.slope.toFixed(1)}° · setup at this site: ${c.minutes} min. ${c.slope>=20?'Steep terrain increases setup time.':c.slope>=10?'The slope increases setup time.':'This site is relatively gentle.'} Consider link status and remaining time before placing. Setup time is a game assumption.</p>`;},report(t,relays,connected){const b=missionBudget(t,relays,mode);return `<h3>Science mission results</h3><p>${MODES[mode].name} selected · setup ${b.install} min + transmission ${b.transfer} min / 45-minute limit.</p><p>${!connected?'The network cannot yet receive records from both crews.':!b.ok?'The network is connected but exceeds the time limit. Try a different site or transmission mode.':mode==='video'?'Live video from both crews has been transmitted! You can compare the rock textures.':'Measurements and compressed photos from both crews have been transmitted.'}</p>`;}};}
